import Image from "next/image";

// COMPETEN SCHOLAR BRAND MARK (SCHOLAR-BRAND-LOGO-01). The owner's Competen Scholar logo, generated by
// scripts/brand/build-scholar-logo.mjs into public/brand/scholar/. Used ONLY where Competen Scholar shows its
// brand: Practice, Enterprise, Professional and HQ keep their own marks (product separation), and the global
// favicon is not touched.
//
// Four cuts of the one mark. The intrinsic sizes below are the generated files' real pixel sizes (they give the
// browser the aspect ratio, so nothing shifts while the image loads); the CSS decides the size shown.
//   emblem          the figure, globe and book alone (square, for a phone header that already names the product)
//   wordmark        "Competen" over "SCHOLAR" (compact headers)
//   lockup          emblem + wordmark (welcome, join, sign-in banner)
//   lockup-tagline  the same with the tagline (the public landing)
//
// ⚠ DARK: the art is a cut-out on transparency. Over a light surface it is exact. Over a dark one the pale
// globe and the navy lettering do not read, so in a dark colour scheme the mark sits on a white rounded tile
// (.cmp-scholar-logo in globals.css) rather than shipping a bad cut-out.
const CUTS = {
  emblem: { src: "/brand/scholar/competen-scholar-emblem.png", width: 512, height: 512 },
  wordmark: { src: "/brand/scholar/competen-scholar-wordmark.png", width: 600, height: 162 },
  lockup: { src: "/brand/scholar/competen-scholar-logo.png", width: 800, height: 723 },
  "lockup-tagline": { src: "/brand/scholar/competen-scholar-logo-tagline.png", width: 900, height: 862 },
} as const;

export type ScholarLogoVariant = keyof typeof CUTS;

/** Fixed size: the mark `height` px tall, its width following the art's own proportions. */
export function ScholarLogo({ variant, height, eager = false, alt = "Competen Scholar", className = "" }: {
  variant: ScholarLogoVariant; height: number; eager?: boolean; alt?: string; className?: string;
}) {
  const c = CUTS[variant];
  const width = Math.round((height * c.width) / c.height);
  return (
    <span className={`cmp-scholar-logo inline-flex shrink-0 leading-[0] ${className}`}>
      <Image src={c.src} alt={alt} width={width} height={height} sizes={`${width}px`} style={{ width, height }}
        loading={eager ? "eager" : "lazy"} fetchPriority={eager ? "high" : "auto"} />
    </span>
  );
}

/** Responsive: fills its container up to `maxWidth` px, height following the art's proportions (no layout shift). */
export function ScholarLogoFluid({ variant, maxWidth, eager = false, alt = "Competen Scholar", className = "" }: {
  variant: ScholarLogoVariant; maxWidth: number; eager?: boolean; alt?: string; className?: string;
}) {
  const c = CUTS[variant];
  return (
    <span className={`cmp-scholar-logo block leading-[0] ${className}`} style={{ maxWidth }}>
      <Image src={c.src} alt={alt} width={c.width} height={c.height} sizes={`(max-width: ${maxWidth}px) 100vw, ${maxWidth}px`}
        style={{ width: "100%", height: "auto" }}
        loading={eager ? "eager" : "lazy"} fetchPriority={eager ? "high" : "auto"} />
    </span>
  );
}
